output_text:
[
  {
    "id": "no_cart_in_single_file_aisles",
    "text": "Shopping carts are forbidden in single-file shelf aisles where the horizontal clearance is only one cell.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "adjShelf",
            "shelfE",
            "shelfW"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "singleFileShelfAisle"
        ]
      }
    }
  },
  {
    "id": "no_push_cart_into_single_file",
    "text": "A shopper must not move a cart into a single-file shelf aisle.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "adjShelf",
            "shelfE",
            "shelfW"
          ]
        }
      },
      "events": {
        "pushCartIntoSingleFileAisle": {
          "pre": {
            "and": [
              "MOVE",
              "hasCart"
            ]
          },
          "post": {
            "and": [
              "singleFileShelfAisle",
              "hasCart"
            ]
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "pushCartIntoSingleFileAisle"
    }
  },
  {
    "id": "park_at_walkin_mouth_before_north",
    "text": "At the mouth of a walk-in item aisle, the cart must not be pushed north into the aisle.",
    "abstraction": {
      "state_properties": {
        "walkInAisleMouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "walkInAisleMouth",
          "hasCart",
          "N"
        ]
      }
    }
  },
  {
    "id": "walk_without_cart_only_in_walkin_zone",
    "text": "After taking a cart, a shopper may walk without it only inside a walk-in aisle or at its parking mouth.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "adjShelf",
            "shelfE",
            "shelfW"
          ]
        },
        "walkInAisleMouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        },
        "cartFreeZone": {
          "or": [
            "singleFileShelfAisle",
            "walkInAisleMouth"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "MOVE",
          {
            "not": "hasCart"
          },
          {
            "not": "cartFreeZone"
          }
        ]
      }
    }
  },
  {
    "id": "retrieve_any_parked_cart",
    "text": "Whenever a shopper sets a cart down, they are obliged to retrieve it before leaving.",
    "abstraction": {
      "state_properties": {},
      "events": {
        "setDownCart": {
          "pre": {
            "and": [
              "INTERACT",
              "hasCart"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        },
        "retrieveCart": {
          "pre": {
            "and": [
              "INTERACT",
              {
                "not": "hasCart"
              }
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "setDownCart",
      "discharge": "retrieveCart"
    }
  },
  {
    "id": "drop_cart_only_at_wide_mouths",
    "text": "A cart may be set down only at a wide cross-aisle mouth of a walk-in aisle, not in narrow shelf space.",
    "abstraction": {
      "state_properties": {
        "walkInAisleMouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        },
        "wideCrossAisleCell": {
          "and": [
            {
              "ge": [
                "freeWidthH",
                12
              ]
            },
            {
              "ge": [
                "freeWidthV",
                5
              ]
            }
          ]
        },
        "legalCartParkingSpot": {
          "and": [
            "walkInAisleMouth",
            "wideCrossAisleCell"
          ]
        }
      },
      "events": {
        "setDownCart": {
          "pre": {
            "and": [
              "INTERACT",
              "hasCart"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "setDownCart",
          {
            "not": "legalCartParkingSpot"
          }
        ]
      }
    }
  },
  {
    "id": "cart_required_for_open_shelf_pickups",
    "text": "For shelf interactions outside single-file walk-in aisles, the shopper should have the cart with them.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "adjShelf",
            "shelfE",
            "shelfW"
          ]
        },
        "openShelfPickupCell": {
          "and": [
            "adjShelf",
            {
              "not": "singleFileShelfAisle"
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "INTERACT",
          "openShelfPickupCell",
          {
            "not": "hasCart"
          }
        ]
      }
    }
  },
  {
    "id": "enter_walkin_only_to_take_item",
    "text": "If a shopper enters a single-file walk-in aisle on foot, they are obliged to perform an item interaction in that aisle before finishing the trip.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "adjShelf",
            "shelfE",
            "shelfW"
          ]
        }
      },
      "events": {
        "enterSingleFileOnFoot": {
          "pre": {
            "and": [
              "MOVE",
              {
                "not": "hasCart"
              },
              {
                "not": "singleFileShelfAisle"
              }
            ]
          },
          "post": "singleFileShelfAisle"
        },
        "interactInSingleFileAisle": {
          "pre": {
            "and": [
              "INTERACT",
              "singleFileShelfAisle",
              {
                "not": "hasCart"
              }
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "enterSingleFileOnFoot",
      "discharge": "interactInSingleFileAisle"
    }
  }
]
